test("lead-time demand is average daily sales times lead time in days", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.deepEqual(result, { leadTimeDemand: 300, safetyStock: 60, reorderPoint: 360, reorder: true });
});

test("safety stock is 20 percent of lead-time demand not of daily sales", function () {
  var result = code.reorderCheck({ averageDailySales: 25, leadTimeDays: 8, stockOnHand: 240 });
  assert.deepEqual(result, { leadTimeDemand: 200, safetyStock: 40, reorderPoint: 240, reorder: true });
});

test("reorder point is lead-time demand plus safety stock", function () {
  var result = code.reorderCheck({ averageDailySales: 80, leadTimeDays: 5, stockOnHand: 480 });
  assert.deepEqual(result, { leadTimeDemand: 400, safetyStock: 80, reorderPoint: 480, reorder: true });
});

test("recommend a reorder when stock on hand is exactly at the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 360 });
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, true);
});

test("do not recommend a reorder when stock on hand is one above the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 361 });
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, false);
});

test("recommend a reorder when stock is one below the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 359 });
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, true);
});

test("recommend a reorder when stock is above lead-time demand but at or below the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 301 });
  assert.equal(result.leadTimeDemand, 300);
  assert.equal(result.reorderPoint, 360);
  assert.equal(result.reorder, true);
});

test("same rule on other quantities when stock is exactly at that reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 10, leadTimeDays: 10, stockOnHand: 120 });
  assert.deepEqual(result, { leadTimeDemand: 100, safetyStock: 20, reorderPoint: 120, reorder: true });
});

test("do not recommend a reorder on other quantities when stock is one above that reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 10, leadTimeDays: 10, stockOnHand: 121 });
  assert.deepEqual(result, { leadTimeDemand: 100, safetyStock: 20, reorderPoint: 120, reorder: false });
});

test("recommend a reorder on other quantities when stock is one below that reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 10, leadTimeDays: 10, stockOnHand: 119 });
  assert.deepEqual(result, { leadTimeDemand: 100, safetyStock: 20, reorderPoint: 120, reorder: true });
});

test("recommend a reorder when stock is between lead-time demand and the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 10, leadTimeDays: 10, stockOnHand: 101 });
  assert.equal(result.leadTimeDemand, 100);
  assert.equal(result.reorderPoint, 120);
  assert.equal(result.reorder, true);
});

test("lead time of one day multiplies daily sales by that lead time", function () {
  var result = code.reorderCheck({ averageDailySales: 40, leadTimeDays: 1, stockOnHand: 48 });
  assert.deepEqual(result, { leadTimeDemand: 40, safetyStock: 8, reorderPoint: 48, reorder: true });
});

test("average daily sales of one multiplies by lead time in days", function () {
  var result = code.reorderCheck({ averageDailySales: 1, leadTimeDays: 5, stockOnHand: 6 });
  assert.deepEqual(result, { leadTimeDemand: 5, safetyStock: 1, reorderPoint: 6, reorder: true });
});

test("stock on hand of zero is below a positive reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 50, leadTimeDays: 6, stockOnHand: 0 });
  assert.deepEqual(result, { leadTimeDemand: 300, safetyStock: 60, reorderPoint: 360, reorder: true });
});

test("larger demand uses 20 percent of lead-time demand and recommends at the reorder point", function () {
  var result = code.reorderCheck({ averageDailySales: 200, leadTimeDays: 7, stockOnHand: 1680 });
  assert.deepEqual(result, { leadTimeDemand: 1400, safetyStock: 280, reorderPoint: 1680, reorder: true });
});
